import type { EngineInterface, Register, ThemeColors, ThemeSetArgs } from 'claude-code'

// A gallery of looks for the desktop and mobile apps, switched with /look.
// One mod holds them all because a session has one theme at a time: separate
// mods would each set theirs at start-up and the last would win.
//
// Generated by scripts/build.mjs from src/bundle-register.tsx. The looks below,
// with each one's computed colors, are filled in at build time, so this one
// file is the whole mod: it carries no helper code and reads no other file.

type Look = {
  id: string
  name: string
  mode: 'dark' | 'light'
  /** The backdrop gradient, top, middle, bottom. */
  sky: readonly [string, string, string]
  /** The accent, for the faint glow in the backdrop's corner. */
  glow: string
  colors: ThemeColors
}

type Api = Pick<EngineInterface, 'theme' | 'store'>

